interface AccountDto {
  id: string;
  currency: 'INR' | 'USD';
  balanceMinor: number; // integer minor units, e.g. paise/cents
}

function displayAmount(minor: number, currency: AccountDto['currency']): string {
  return new Intl.NumberFormat('en-IN', {
    style: 'currency', currency
  }).format(minor / 100);
}

const account: AccountDto = {
  id: 'ACC-42', currency: 'INR', balanceMinor: 125050
};
console.log(displayAmount(account.balanceMinor, account.currency));
// displayAmount(account.id, account.currency); // TS error: string is not number

interface Product {
  id: string;
  priceMinor: number;
  status: InventoryStatus;
}

type InventoryStatus = 'in-stock' | 'out-of-stock';

class CartLine {
  constructor(public readonly product: Product, public readonly quantity: number) {}

  totalMinor(): number {
    return this.product.priceMinor * this.quantity;
  }
}

const product: Product = {
  id: 'sku-7', priceMinor: 4999, status: 'in-stock'
};
const line = new CartLine(product, 2);
console.log(line.totalMinor()); // 9998
console.log(line instanceof CartLine); // true
// Product and InventoryStatus have no runtime constructor to use with instanceof.

type AppointmentStatus = 'requested' | 'confirmed' | 'cancelled';

interface Appointment {
  id: string;
  status: AppointmentStatus;
  note?: string;
}

interface ApiResponse<T> {
  data: T;
  requestId: string;
}

function describe<T extends { id: string }>(response: ApiResponse<T>): string {
  return `Item ${response.data.id}, request ${response.requestId}`;
}

const response: ApiResponse<Appointment> = {
  data: { id: 'apt-8', status: 'confirmed' },
  requestId: 'req-99'
};
const noteText = response.data.note ?? 'No note provided';
console.log(noteText); // No note provided
console.log(describe(response)); // Item apt-8, request req-99
// response.data.status = 'unknown'; // compile-time error

type Status = 'created' | 'delivered';

function parseStatus(value: unknown): Status | null {
  if (value === 'created' || value === 'delivered') return value;
  return null;
}

function assertNever(value: never): never {
  throw new Error(`Unhandled status: ${String(value)}`);
}

function labelStatus(status: Status): string {
  switch (status) {
    case 'created': return 'Shipment created';
    case 'delivered': return 'Delivered';
    default: return assertNever(status);
  }
}

function logStatus(raw: unknown): void {
  const status = parseStatus(raw);
  console.log(status === null ? 'Invalid status' : labelStatus(status));
}

logStatus('delivered'); // Delivered
logStatus(42); // Invalid status
