type Role = 'customer' | 'admin';
type Currency = 'INR' | 'USD';

interface User {
  readonly id: string;
  readonly name: string;
  readonly role: Role;
}

interface Account {
  readonly id: string;
  readonly ownerUserId: User['id'];
  readonly currency: Currency;
  readonly balanceMinor: number;
}

type ApiResponse<T> =
  | { ok: true; data: T; requestId: string }
  | { ok: false; error: { code: string; message: string }; requestId: string };

function summarizeAccount(response: ApiResponse<Account>): string {
  if (!response.ok) return `Error: ${response.error.code}`;
  const account = response.data; // narrowed to Account
  return `${account.id}: ${account.balanceMinor} minor units (${account.currency})`;
}

const user: User = { id: 'u-3', name: 'Asha', role: 'customer' };
const success: ApiResponse<Account> = {
  ok: true,
  data: { id: 'acc-3', ownerUserId: user.id, currency: 'INR', balanceMinor: 45050 },
  requestId: 'req-123'
};
const failure: ApiResponse<Account> = {
  ok: false,
  error: { code: 'ACCOUNT_NOT_FOUND', message: 'Account not found' },
  requestId: 'req-124'
};
console.log(summarizeAccount(success));
console.log(summarizeAccount(failure));
